import { readFile, writeFile } from 'node:fs/promises';
import openapiTS, { astToString } from 'openapi-typescript';
const input = new URL('../openapi.json', import.meta.url);
const output = new URL(
  '../../solve-tracker-frontend/src/lib/api/generated/backend.d.ts',
  import.meta.url,
);
const content =
  '// Generated by pnpm api:generate. Do not edit.\n' +
  astToString(await openapiTS(input));
if (process.argv.includes('--check')) {
  if ((await readFile(output, 'utf8')) !== content)
    throw new Error('API types are stale. Run pnpm api:generate.');
} else {
  await writeFile(output, content);
}
console.log(
  process.argv.includes('--check')
    ? 'API types verified.'
    : 'API types generated.',
);
